// Non-secret settings for ff-website-check. n8n credential: FF Supabase (service role).
// Daily 06:45 for every client (after the sync), and when a client is saved on the dashboard.
// Webhook body (optional): { client_id }
// Reads public pages only - no login to any website, nothing personal is kept.
const SETTINGS = {
  SUPABASE_URL: 'https://SET-ME.supabase.co',
  SUPABASE_ANON_KEY: 'SET-ME',
  ALLOWED_ROLES: ['rob_admin', 'ff_staff'],
  GHL_COMPANY_ID: 'SET-ME', // only a fallback - the agency id is read from a client already linked to GHL
};

const src = $input.first().json || {};
const fromWebhook = Boolean(src.headers);
const body = fromWebhook && src.body && typeof src.body === 'object' ? src.body : {};
const uuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

return [{
  json: {
    ...SETTINGS,
    body,
    trigger: fromWebhook ? 'manual' : 'schedule',
    only_client_id: typeof body.client_id === 'string' && uuid.test(body.client_id) ? body.client_id : null,
  },
}];

// Auth check block 1/4 - read the bearer token. Never log it.
const headers = $('Webhook').first().json.headers || {};
const raw = headers.authorization || headers.Authorization || '';
const match = /^Bearer\s+(\S+)$/i.exec(String(raw).trim());
return [{ json: { token: match ? match[1] : '' } }];

// Auth check block 4/4 - decide. Output: { ok, status, error?, user? }
const cfg = $('Config').first().json;
const token = $('Auth: read token').first().json.token;
const userRes = $('Auth: verify token').first().json;
const profileRes = $('Auth: load profile').first().json;

const deny = (status, error) => [{ json: { ok: false, status, error } }];

if (!token) return deny(401, 'Missing login token.');
if (userRes.statusCode !== 200 || !userRes.body || !userRes.body.id) {
  return deny(401, 'Login token is not valid or has expired.');
}
if (profileRes.statusCode !== 200) return deny(500, 'Could not load the login profile.');

const rows = Array.isArray(profileRes.body) ? profileRes.body : [];
const profile = rows[0];
if (!profile || profile.user_id !== userRes.body.id) return deny(403, 'This login has no access.');
if (profile.disabled) return deny(403, 'This login has been turned off.');
if (!cfg.ALLOWED_ROLES.includes(profile.role)) {
  return deny(403, 'Your role does not allow this action.');
}

return [{
  json: {
    ok: true,
    status: 200,
    user: {
      user_id: profile.user_id,
      email: profile.email,
      role: profile.role,
      client_id: profile.client_id,
    },
  },
}];

// One item per page to check: the client's website (Edit client) and the landing
// pages of its enabled ads (from ff_website_targets), at most 5 per client.
// Emits { none: true } when there is nothing to check.
const rows = $input.all().map((i) => i.json).filter((r) => r && r.client_id && Array.isArray(r.urls));
const out = [];
for (const r of rows) {
  const seen = new Set();
  for (const raw of r.urls) {
    const url = String(raw || '').trim();
    if (!/^https?:\/\/[^\s]+$/i.test(url) || url.length > 500 || seen.has(url)) continue;
    seen.add(url);
    out.push({ json: { client_id: r.client_id, process: r.process, url } });
    if (seen.size >= 5) break;
  }
}
return out.length ? out : [{ json: { none: true } }];

// Reads each fetched public page (no login) and records what is on it - never
// any text or personal data from the page, only yes/no answers, tag ids and a
// count of phone links. Each answer is matched to its page with itemMatching(i).
// Pages built in the browser (some site builders) or tags loaded through Google
// Tag Manager may not show in the HTML; the dashboard says so.
const now = new Date().toISOString();
const rows = [];
$input.all().forEach((item, i) => {
  const page = $('Pages').itemMatching(i).json;
  const r = item.json || {};
  const ok = r.statusCode >= 200 && r.statusCode < 400;
  const html = typeof r.body === 'string' ? r.body.slice(0, 3000000) : typeof r.data === 'string' ? r.data.slice(0, 3000000) : '';
  const h = html.toLowerCase();
  const has = (re) => re.test(h);

  const ids = [...new Set((html.match(/\b(AW-\d{6,12}|G-[A-Z0-9]{6,12}|GTM-[A-Z0-9]{4,10})\b/g) || []))].slice(0, 10);
  const ffSettings = ['phone-conversion', 'form-conversion', 'thank-you-path', 'start-conversion', 'purchase-conversion', 'purchase-path']
    .filter((k) => h.includes(`data-${k}`));
  const ghlForm = has(/(leadconnectorhq\.com|msgsndr\.com)\/widget\/(form|survey|booking)|form_embed\.js/);
  const leadForm = ghlForm || has(/<form[\s\S]{0,6000}?(type=["']?(email|tel)\b|name=["']?(email|phone)\b)/);
  let checkout = null;
  if (has(/js\.stripe\.com|checkout\.stripe\.com|buy\.stripe\.com/)) checkout = 'stripe';
  else if (has(/woocommerce/)) checkout = 'woocommerce';
  else if (has(/paypal\.com\/sdk|paypalobjects\.com/)) checkout = 'paypal';
  else if (has(/squareup\.com|square\.site/)) checkout = 'square';
  else if (has(/(leadconnectorhq\.com|msgsndr\.com)[^"']*(order|payment)|order-form/)) checkout = 'ghl order form';
  else if (has(/href=["'][^"']*(checkout|arrange-online|arrange-now|pay-online|pay-now)[^"']*["']/)) checkout = 'checkout link';
  let platform = 'other';
  if (has(/wp-content|wp-includes/)) platform = 'wordpress';
  else if (has(/assets\.cdn\.filesafe\.space|leadconnectorhq|msgsndr/) && has(/__nuxt|nuxt/)) platform = 'ghl';
  else if (has(/wixstatic\.com|wix\.com/)) platform = 'wix';
  else if (has(/squarespace/)) platform = 'squarespace';
  else if (has(/cdn\.shopify\.com/)) platform = 'shopify';

  rows.push({
    client_id: page.client_id,
    url: page.url,
    checked_at: now,
    status_code: r.statusCode || null,
    error: ok ? null : String((r.error && r.error.message) || `status ${r.statusCode || 'none'}`).slice(0, 200),
    platform: ok ? platform : null,
    has_ff_script: ok && h.includes('ff-click-id.js'),
    ff_settings: ok ? ffSettings : [],
    has_gtag: ok && has(/googletagmanager\.com\/gtag\/js|gtag\(/),
    gtag_ids: ok ? ids : [],
    has_gtm: ok && has(/googletagmanager\.com\/gtm\.js|\bgtm-[a-z0-9]{4,10}\b/),
    has_ghl_form: ok && ghlForm,
    has_form: ok && leadForm,
    has_checkout: ok && Boolean(checkout),
    checkout_hint: ok ? checkout : null,
    phones_seen: ok ? (h.match(/href=["']tel:/g) || []).length : 0,
  });
});
return [{ json: { rows, count: rows.length } }];

// Links clients that have no GHL sub-account yet to FF's GHL sub-accounts, by
// themselves: same business name, same website, or same business phone. Only an
// unambiguous match is saved (one sub-account for one client, not used by
// another client). Output: Supabase PATCH items for "Save GHL links", or one
// no-op item. Business names, websites and phones only - no family data.
const res = $('GHL: list sub-accounts').first().json || {};
const clients = $('Clients without GHL').all().map((i) => i.json).filter((c) => c && c.client_id);
const linked = new Set($('Linked GHL sub-accounts').all().map((i) => i.json && i.json.ghl_location_id).filter(Boolean));
const NOOP = [{ json: { method: 'GET', path: 'clients?select=id&limit=0', body: null, matched: 0 } }];

if (!(res.statusCode >= 200 && res.statusCode < 300) || !clients.length) return NOOP;
const locations = ((res.body && res.body.locations) || []).filter((l) => l && l.id && !linked.has(l.id));

const STOP = new Set(['the', 'inc', 'ltd', 'llc', 'co', 'and', 'of', 'corp', 'company']);
const name = (s) => String(s || '').toLowerCase().replace(/&/g, ' and ').replace(/[^a-z0-9]+/g, ' ').split(' ')
  .filter((w) => w && !STOP.has(w)).join(' ');
const host = (s) => {
  const m = /^(?:https?:\/\/)?(?:www\.)?([^/?#:]+)/i.exec(String(s || '').trim());
  return m ? m[1].toLowerCase() : '';
};
const phone = (s) => String(s || '').replace(/\D/g, '').slice(-10);

const out = [];
const used = new Set();
for (const c of clients) {
  const hits = locations.filter((l) => !used.has(l.id) && (
    (name(c.name) && name(l.name) === name(c.name))
    || (host(c.website_url) && host(l.website) === host(c.website_url))
    || (phone(c.phone).length === 10 && phone(l.phone) === phone(c.phone))
  ));
  if (hits.length !== 1) continue;
  used.add(hits[0].id);
  out.push({ json: {
    method: 'PATCH',
    path: `clients?id=eq.${c.client_id}&ghl_location_id=is.null`,
    prefer: 'return=minimal',
    body: { ghl_location_id: String(hits[0].id) },
    matched: 1,
  } });
}
return out.length ? out : NOOP;
